'use strict';
const DATA=window.MiniopolyCentralData;
const ICONS={dice:'M12 2 3 7v10l9 5 9-5V7L12 2Zm0 0v10m-9-5 9 5 9-5m-9 5v10M7 9l2 1m6 5 2-1m-1 4 2-1',home:'m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7',save:'M5 3h12l4 4v14H3V3h2Zm2 0v6h10V3M7 21v-8h10v8',play:'m9 5 11 7-11 7V5Z',book:'M3 4h6c2 0 3 1 3 3v15c0-2-2-3-4-3H3V4Zm18 0h-6c-2 0-3 1-3 3v15c0-2 2-3 4-3h5V4Z',trophy:'M7 3h10v6c0 4-2 6-5 6S7 13 7 9V3Zm0 2H3v3c0 3 2 4 5 4m9-7h4v3c0 3-2 4-5 4m-4 3v5m-5 1h10',wifi:'M2 8c5-5 15-5 20 0M5 12c4-4 10-4 14 0m-11 4c2-2 6-2 8 0m-4 4h.01',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 6 5 12 0 18-5-6-5-12 0-18Z',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',pin:'M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 0 1 14 0Zm-4 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',people:'M16 21v-2c0-4-12-4-12 0v2m9-13a4 4 0 1 1-8 0 4 4 0 0 1 8 0Zm5 5c3 0 5 2 5 4v3m-6-17a4 4 0 0 1 0 8',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9-5v5l3 2',check:'m5 12 4 4L19 6',cards:'m7 3 13 3-4 15-13-3L7 3Zm5 2 9 4-6 12M9 9l5 1m-6 3 5 1',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-1 5 6 6',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9-1v6m0-10h.01',crown:'m3 6 5 5 4-7 4 7 5-5-2 13H5L3 6Z',upload:'M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5',more:'M4 12h.01M12 12h.01M20 12h.01',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z',map:'m3 5 6-3 6 3 6-3v17l-6 3-6-3-6 3V5Zm6-3v17m6-14v17'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]||ICONS.info}"></path></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+Number(n).toLocaleString('en-US');
const colors={Brown:'#99704c',Blue:'#58a7be',Pink:'#d580a0',Orange:'#e39b50',Red:'#cd695b',Yellow:'#ddc365',Green:'#6aa479',Navy:'#6374a6'};
const symbols={festival:'✦',start:'⚑',rail:'🚂',chest:'🎁',chance:'?',weather:'?',bonus:'✦',util:'⚡',trouble:'↶',tax:'$'};
const pill=(text,style='')=>`<span class="pill ${style}">${text}</span>`;
function intro(title,copy,extra='',eyebrow='YOUR GAME NIGHT'){return `<div class="page-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${copy}</p></div>${extra}</div>`;}
function avatar(index,alt=''){return `<img src="${DATA.avatars[index]}" alt="${esc(alt)}">`;}
function learnView(){const tabs=[['overview','Start here'],['rules','Game rules'],['boards','Worlds & boards'],['properties','Properties']];return `${intro('A little knowledge. A better first game.','Explore at your own pace before you take a seat.','','LEARN THE GAME')}<div class="tabs" role="tablist" aria-label="Learning sections">${tabs.map(([id,label])=>`<button class="tab" role="tab" id="learn-tab-${id}" aria-controls="learningContent" aria-selected="${state.learnTab===id}" tabindex="${state.learnTab===id?'0':'-1'}" data-learn-tab="${id}">${label}</button>`).join('')}</div><section id="learningContent" role="tabpanel" aria-labelledby="learn-tab-${state.learnTab}">${state.learnTab==='overview'?learnOverview():state.learnTab==='rules'?rulesView():state.learnTab==='boards'?boardsView():propertiesView()}</section>`;}
function learnOverview(){return `<div class="learn-intro"><div><span class="eyebrow">WELCOME TO YOUR FIRST GAME</span><h2>Roll. Explore. Build your little empire.</h2><p>Buy properties, collect rent and find your way through three connected worlds. Choose a round limit, or play until one player remains.</p></div><button class="button" data-action="rules">Learn the rules ${icon('arrow')}</button></div><div class="steps">${[['1','Roll & travel','Roll the 12-sided die. Follow your piece around the board—and keep an eye out for a world shift.'],['2','Buy & build','Buy available properties. Complete color sets across the worlds to unlock upgrades and increase your rent.'],['3','Grow your worth','Collect rent and make your next move count. A fixed-round match is decided by final net worth.']].map(([n,title,copy])=>`<article class="panel step"><span class="step-number">${n}</span><h3>${title}</h3><p>${copy}</p></article>`).join('')}</div><div class="section-head"><h2>Three worlds. Plenty to discover.</h2></div><div class="worlds-row">${DATA.worlds.map((w,i)=>`<button class="world-card" data-action="world" data-world="${i}"><img src="${DATA.scenes[i]}" alt="${w.name} scenery"><div><h3>${w.name}</h3><p>${['Live oaks, familiar streets and a salt-marsh sunset.','Garden paths and neighborhoods that feel like home.','Sea breezes, tidal waters and new possibilities.'][i]}</p><span class="text-link">Explore this board ${icon('arrow')}</span></div></button>`).join('')}</div>`;}
const rules=[['Disaster Season · Tsunami','Build for 10, 15 or 20 rounds; sirens reveal a fixed wave direction in the final two building rounds. North/south threatens the top and bottom rows; east/west threatens the side columns. Five waves strike up to three owned properties total along the exposed edges of all neighborhoods. Exact targets are selected at impact; surviving properties can be struck again. Built-in protection costs one development and works once per property. Wave Shield cards protect one property for one wave without spending its built-in protection. Lost deeds become submerged sites with no rent or value. Submit secret bids after waves, then pay the displayed rebuilding cost on your turn to restore base rent and value. Only winners pay; tied highest bids are drawn randomly. No-deed players can recover; bankruptcy still eliminates. After wave five, one calm recovery round allows final rebuilding, then highest net worth wins; equal scores share victory.'],['Express · World Collapse','Choose 10, 15 or 20 building rounds. Each player receives two random homes worth $400 total and a Building Permit. Passing GO adds a free available home to the normal $200 reward; another permit arrives halfway through. The last five building rounds show increasingly strong warnings. After the full building period, marked deeds collapse in waves. Every wave has one complete round of notice. Properties earn 1 construction point each, plus 1 per upgraded property. At least 3 properties are required; every 3 points earns one evade token, capped at 3 and locked before the first wave. Tokens protect a first landing on a void; revisiting that same void is fatal. Landing without protection eliminates only the roller; passing over it or already standing there is safe. A fatal shift cancels Gravity Pull. Lost deeds are worth $0 and cannot earn rent, be upgraded, sold or traded. Last player standing wins. Express results have their own standings. Final Showdown is an optional 50% rent increase during collapse.'],['Community Festival','Paid Town Tax and Storm Fund payments build one shared fund across every world. The festival corner replaces Community Bonus in The Communities. The visitor receives 60%; the other 40% is split among nonbankrupt players, including those in Setback. Whole dollars are paid in turn order and the fund resets to zero. An empty fund pays nothing.'],['The aim of the game','In a fixed-round match, finish with the highest net worth. Net worth is cash plus the purchase price of unmortgaged deeds plus half the cost of upgrades. Equal net worth shares a financial rank. In Unlimited play, the last player remaining after the others go bankrupt wins.'],['Your turn, step by step','Roll the 12-sided die and wait for your piece to arrive. Resolve the landing: buy or pass on an available deed, pay rent or a bank payment, or read your drawn card. You can review holdings and eligible upgrades before ending your turn.'],['Bonus rolls: 7 or 11','A 7 or 11 earns another roll after you resolve the landing. The Bonus Roll button rolls immediately. Three consecutive 7-or-11 rolls send the player to Setback in the current world. A different roll ends the chain.'],['World shifts & Gravity Pull','A roll of 6 or 12 shifts worlds before the move; ten rolls without a shift also trigger a shift. Individual moves only the roller. Gravity Pull brings eligible players to the roller’s exact dice destination. Only the roller resolves the landing; pulled players get no GO payment or extra landing event. Players held in Setback stay put.'],['Properties, color sets & upgrades','Every owned, unmortgaged deed can earn rent. Complete a color set across the worlds to unlock normal house upgrades. A Building Permit gives one free upgrade without needing the full set. The property must be owned, unmortgaged and below Level 3.'],['Setback & escape','Landing on the Setback square is just visiting. You can be sent there by three consecutive 7-or-11 rolls or a card. While held, choose a free escape attempt rolling 6 or 12, a paid roll costing 20 times the result, a deed forfeiture or an escape card. After three failed free attempts, payment for the third result is required. Escape rolls never shift worlds or grant bonuses. Rent collection pauses while held.'],['GO, cards & special places','Passing GO normally pays $200; landing directly on GO pays the GO landing bonus. Community Chest and Chance can award money, require payments, move you or give a saved perk. Railroads and utilities have their own rent rules. Click their spaces on a board to explore them.'],['Match length & changing rules','Choose 10, 12, 15, 20, 30 or 50 rounds, or Unlimited. The room’s host may change the round limit or World shift mode during play; a new shift mode applies to the next roll. Starting cash locks after starting. Shared changes are announced to all players. Ranked 10/15/20-round games with $1,500 starting cash earn separate Individual or Gravity Pull records. Rule changes make a game practice.']];
function rulesView(){return `<div class="learn-intro"><div><h2>The rules, without the guessing.</h2><p>Open a topic for a quick explanation. Board and property previews are always a click away.</p></div><button class="button secondary" data-action="worlds">${icon('map')} See the boards</button></div><div class="rules-grid">${rules.map(([title,copy],index)=>`<details class="rule" ${index===0?'open':''}><summary>${title}</summary><p>${copy}</p></details>`).join('')}</div>`;}
function worldTabs(){return `<div class="toolbar">${DATA.worlds.map((w,i)=>`<button class="mode-chip ${state.world===i?'active':''}" aria-pressed="${state.world===i}" data-world-select="${i}">${w.name}</button>`).join('')}</div>`;}
function boardsView(){const w=DATA.worlds[state.world];return `${worldTabs()}<div class="world-heading"><div><h2>${w.name}</h2><p>Select any space to discover what happens there.</p></div>${pill('Board explorer · 16 spaces','gold')}</div><div class="board-layout"><div class="map-board" aria-label="${w.name} board layout"><div class="map-center" style="background-image:url('${DATA.scenes[state.world]}')"><h3>${w.name}</h3><p>${['LIVE OAKS · SALT MARSH · HOME','GARDEN PATHS · GATHERING PLACES','SEA BREEZES · TIDAL WATERS'][state.world]}</p><span>${icon('map')} Explore every space</span></div>${w.tiles.map((tile,index)=>{const id=state.world+'-'+index,d=DATA.deeds.find(d=>d.id===id),pos=index<=4?[1,index+1]:index<=8?[index-3,5]:index<=12?[5,13-index]:[17-index,1];return `<button class="map-tile" style="grid-area:${pos[0]}/${pos[1]};--color:${colors[d?.color]||'#aac4a1'}" data-action="space" data-world="${state.world}" data-position="${index}" aria-label="Space ${index+1}: ${esc(tile[1])}">${d?.type==='p'?`<img src="${DATA.art[id]}" alt=""><strong>${d.name}</strong><small>${money(d.price)}</small>`:`<span class="tile-symbol" aria-hidden="true">${symbols[tile[0]]||'✦'}</span><strong>${esc(tile[1])}</strong>`}</button>`;}).join('')}</div><aside class="board-aside"><section class="panel"><span class="eyebrow">FIND YOUR WAY</span><h3 style="margin-top:9px">One board. Sixteen possibilities.</h3><p>Start at GO in the upper-left corner and move clockwise. Properties share colors with sets in the other worlds.</p><div class="legend"><span><i style="--color:#a58c68"></i> Properties you can buy & upgrade</span><span><i style="--color:#8eacc6"></i> Railroads & utilities</span><span><i style="--color:#b5a1c7"></i> Cards, rewards & surprises</span></div></section><section class="panel"><h3>Look beyond this world.</h3><p>Your next set member may be in another world. Use the property explorer to see the full picture.</p><button class="text-link" data-action="properties">Explore all properties ${icon('arrow')}</button></section></aside></div>`;}
function propertiesView(){return `<div class="section-head"><div><h2>Find your next favorite property.</h2><p>Browse every deed. Click a card for rent and upgrade details.</p></div><span class="small-copy" id="propertyCount"></span></div><div class="toolbar"><label class="search-wrap">${icon('search')}<input id="propertySearch" type="search" placeholder="Search properties…" aria-label="Search property names" value="${esc(state.propertySearch)}"></label><label>World<select id="propertyWorld"><option value="all">All worlds</option>${DATA.worlds.map((w,i)=>`<option value="${i}" ${String(state.propertyWorld)===String(i)?'selected':''}>${w.name}</option>`).join('')}</select></label><label>Type<select id="propertyType"><option value="all">All deeds</option><option value="p" ${state.propertyType==='p'?'selected':''}>Properties</option><option value="rail" ${state.propertyType==='rail'?'selected':''}>Railroads</option><option value="util" ${state.propertyType==='util'?'selected':''}>Utilities</option></select></label></div><div class="property-grid" id="propertyGrid">${propertyCards()}</div><div class="info-note">${icon('cards')}<span>Color sets span worlds: Brown and Navy have 2 properties each; the other sets have 3. Full sets unlock normal upgrades. Railroads and utilities are separate deeds.</span></div>`;}
function filteredProperties(){return DATA.deeds.filter(d=>(state.propertyWorld==='all'||d.board===Number(state.propertyWorld))&&(state.propertyType==='all'||d.type===state.propertyType)&&d.name.toLowerCase().includes(state.propertySearch.toLowerCase()));}
function propertyCards(){const properties=filteredProperties();return properties.length?properties.map(d=>`<button class="property-card" data-action="property" data-id="${d.id}" style="--color:${colors[d.color]||'#8eaebe'}">${d.type==='p'?`<img src="${DATA.art[d.id]}" alt="${d.name} scenery">`:`<span class="property-symbol" aria-hidden="true">${d.type==='rail'?'🚂':'⚡'}</span>`}<span class="color-bar"></span><div class="property-card-body"><h3>${d.name}</h3><small>${DATA.worlds[d.board].name}</small><div class="property-card-bottom"><b>${money(d.price)}</b><span>${d.type==='p'?'Rent '+money(d.base):d.type==='rail'?'Railroad':'Utility'}</span></div></div></button>`).join(''):'<div class="empty">No matching properties. Try another world or search.</div>';}
function updateProperties(){document.getElementById('propertyGrid').innerHTML=propertyCards();document.getElementById('propertyCount').textContent=filteredProperties().length+' deeds';}
function toast(text){const node=document.getElementById('toast');node.textContent=text;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,4500);}
function modal(title,eyebrow,body){if(!document.getElementById('dialog').open)returnFocus=document.activeElement;document.getElementById('dialogEyebrow').textContent=eyebrow;document.getElementById('dialogBody').innerHTML=`<h2 id="dialogTitle">${title}</h2>${body}`;const dialog=document.getElementById('dialog');if(!dialog.open)dialog.showModal();}
function closeDialog(){const dialog=document.getElementById('dialog');if(dialog.open)dialog.close();}
function propertyDialog(id){const d=DATA.deeds.find(d=>d.id===id);if(!d)return;modal(d.name,'EXPLORE A DEED',`<p class="dialog-description">${DATA.worlds[d.board].name} · ${d.color?d.color+' set':d.type==='rail'?'Railroad':'Utility'}</p>${d.type==='p'?`<img class="dialog-art" src="${DATA.art[id]}" alt="${d.name} scenery">`:''}<div class="dialog-summary"><div class="summary-row"><span>Purchase price</span><b>${money(d.price)}</b></div>${d.type==='p'?`<div class="summary-row"><span>Standard upgrade cost</span><b>${money(d.upgradeCost)} per level</b></div><div class="summary-row"><span>Set size</span><b>${['Brown','Navy'].includes(d.color)?2:3} properties across worlds</b></div>`:''}</div>${d.type==='p'?`<h3 style="font-size:15px;margin-top:18px">Rent at a glance</h3><div class="detail-rents">${[1,2,4,7].map((m,l)=>`<div><span>${l?'Level '+l:'No upgrades'}</span><b>${money(d.base*m)}</b></div>`).join('')}</div><p class="small-copy" style="margin-top:15px">Complete the set to unlock paid upgrades. Tsunami paid upgrades cost twice the standard price. A Building Permit gives one free upgrade without the full set, on an owned, unmortgaged house below Level 3.</p>`:`<p class="dialog-description">${d.type==='rail'?'Railroad rent is $25, $50, $100 or $200 when the owner holds 1, 2, 3 or 4 railroads.':'Utility rent is 4 times the landing roll for one utility, or 10 times with both utilities.'} Mortgaged deeds do not collect rent.</p>`}<div class="dialog-actions"><button class="button secondary" data-action="close">Back to exploring</button></div>`);}
function spaceDialog(world,position){const id=world+'-'+position,d=DATA.deeds.find(d=>d.id===id);if(d)return propertyDialog(id);const tile=DATA.worlds[world].tiles[position],copy={festival:'Paid Town Tax and Storm Fund charges build one shared Festival fund across all worlds. Landing here pays 60% to the visitor and splits 40% among other nonbankrupt players, including those in Setback. Whole dollars are distributed in turn order; the fund resets to zero.',start:'This is where your journey begins. Passing GO normally pays $200; landing directly on GO pays the GO landing bonus.',chest:'Draw a Community Chest card. It may bring a reward, an expense, a saved perk or another surprise.',chance:'Draw a special card and read its result. Lucky Draw gives a positive cash surprise; Traffic Surprise can help or hinder you.',weather:'Draw a Chance card for a mixed surprise. Read the card before you continue.',bonus:'Receive a Community bonus or card. Coastal Bonus awards $75.',trouble:'Landing here is just visiting. Being sent to Setback holds your piece and pauses rent collection. See Game rules for your escape choices.',tax:'A bank payment is due: '+(tile[1]==='Storm Fund'?'$125':'$100')+'. Paid taxes enter the shared Community Festival fund. You can review your cash and assets before settling.'};modal(esc(tile[1]),DATA.worlds[world].name.toUpperCase()+' · SPECIAL SPACE',`<p class="dialog-description">${copy[tile[0]]||'A special space with its own event.'}</p><div class="dialog-actions"><button class="button secondary" data-action="close">Keep exploring</button><button class="button" data-action="rules">View the rules ${icon('arrow')}</button></div>`);}
const state={page:'home',learnTab:'overview',world:0,propertyWorld:'all',propertySearch:'',propertyType:'all',saveStatus:'all',rankRounds:10,homeRounds:10,homeShift:'individual',rankType:'legendary',rankShift:'individual',rankCash:1500,hostMode:'local'};
const navItems=[['home','home','Game Launcher'],['saves','save','Saved Games'],['host','play','Host & Join'],['learn','book','Learn the Game'],['ranks','trophy','Hall of Fame']];
let returnFocus=null,toastTimer=null,hub=null,saves=[],centralError='',refreshing=false;
let ownerToken='';try{const fragment=location.hash.slice(1);if(/^[a-f0-9]{64}$/.test(fragment)){sessionStorage.setItem('miniopoly_host_console',fragment);history.replaceState(null,'',location.pathname+location.search);}ownerToken=sessionStorage.getItem('miniopoly_host_console')||'';}catch{}
let defaults={hostName:'Host',capacity:4,rounds:20,worldShift:'individual',startingCash:1500,ranked:false};
try{Object.assign(defaults,JSON.parse(localStorage.getItem('miniopoly_match_defaults_v1')||'{}'));const query=new URLSearchParams(location.search);if(query.has('hostSetup'))Object.assign(defaults,JSON.parse(query.get('hostSetup')));const u=new URL(query.get('setupConsole'));if(u.protocol==='http:'&&u.hostname==='127.0.0.1'&&u.port&&!u.username&&!u.password&&u.pathname==='/'&&!u.search&&!u.hash)localStorage.setItem('miniopoly_setup_console_v1',u.origin);}catch{}
if(location.search)history.replaceState(null,'',location.pathname+location.hash);
DATA.scenes.forEach((scene,index)=>document.documentElement.style.setProperty('--scene-'+index,`url("${scene}")`));
document.getElementById('nav').innerHTML=navItems.map(([id,im,label])=>`<a class="nav-link" href="#${id}" data-nav="${id}" title="${label}">${icon(im)}<span>${label}</span></a>`).join('');
document.querySelectorAll('[data-icon]').forEach(node=>node.innerHTML=icon(node.dataset.icon));
const avatarIndex=value=>{const match=String(value||'').match(/^(man|woman)-([1-5])$/);return match?(match[1]==='woman'?5:0)+Number(match[2])-1:0;};
const isOwner=()=>hub?.role==='owner';
const mode=()=>isOwner()?hub.hosting?.mode||'local':hub?.connection?.remote?'online':'local';
const ready=()=>!isOwner()||hub?.hosting?.phase==='ready';
const profileName=()=>isOwner()?hub.hosting?.gameSettings?.hostName||'Host':saves.find(s=>s.viewerName)?.viewerName||defaults.hostName||'Player';
const when=value=>value?new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'Saved on this host';
function saveCard(save){const finished=save.stage==='finished',world=save.players.find(p=>p.name===save.turnName)?.board??save.players[0]?.board??0;return `<article class="save-card"><div class="save-image" style="background-image:url('${DATA.scenes[world]}')"><span class="save-world">${DATA.worlds[world].name}</span></div><div class="save-content"><div class="save-title-row"><h3>${esc(save.name)}</h3><button class="icon-button" data-action="resume" data-id="${save.code}" aria-label="Details for ${esc(save.name)}">${icon('more')}</button></div><p class="save-meta">${when(save.updatedAt)} · ${save.code}</p><div class="save-pills">${pill(finished?'Match complete':save.stage==='lobby'?'Waiting room':save.rounds?'Round '+save.round+' of '+save.rounds:'Round '+save.round+' · Unlimited',finished?'subtle':'gold')}${pill(['express','countdown'].includes(save.gameMode)?(save.gameMode==='countdown'?'Tsunami · ':'Express · ')+(save.collapseWave?(save.gameMode==='countdown'?'Wave ':'Collapse Wave ')+save.collapseWave:save.rounds+' building rounds'):'Classic')}${pill(save.worldShift==='gravity'?'Gravity Pull':'Individual')}</div><div class="save-bottom"><div class="mini-avatars">${save.players.slice(0,3).map(p=>avatar(avatarIndex(p.avatar),p.name)).join('')}<span>${save.players.length} players</span></div><button class="button" data-action="resume" data-id="${save.code}">${finished?'Results':'Continue'} ${icon('arrow')}</button></div></div></article>`;}
function entries(kind=state.rankType,round=state.rankRounds){
 let list=[];
 if(kind==='legendary')list=state.rankCash===1500?[...((state.rankShift==='gravity'?hub?.legendaryGravity:hub?.legendary)?.[round]||[])].map(p=>({...p,avatarIndex:0,roomName:'Legendary record'})):[];
 else for(const record of hub?.records||[])if(record.roundLimit===Number(round)&&record.worldShift===state.rankShift&&record.startingCash===state.rankCash&&(record.gameMode||'classic')===(state.rankGameMode||'classic')&&(state.rankGameMode!=='express'||record.collapseRentBoost===!!state.rankRentBoost))for(const p of record.standings)list.push({...p,at:record.at,roomName:record.name,roundsPlayed:record.roundsPlayed,reason:record.reason,ranked:record.ranked,avatarIndex:avatarIndex(p.avatar),matchId:record.matchId});
 list.sort((a,b)=>kind==='standings'&&['express','countdown'].includes(state.rankGameMode)?String(b.at).localeCompare(String(a.at))||a.matchId.localeCompare(b.matchId)||a.place-b.place:kind==='standings'&&Number(round)===0?String(b.at).localeCompare(String(a.at))||a.matchId.localeCompare(b.matchId)||Number(!!a.bankrupt)-Number(!!b.bankrupt)||b.worth-a.worth||a.seat-b.seat:Number(!!a.bankrupt)-Number(!!b.bankrupt)||b.worth-a.worth||String(a.at).localeCompare(String(b.at))||a.seat-b.seat);
 return list.map(p=>({...p,rank:p.bankrupt?null:list.findIndex(other=>!other.bankrupt&&other.worth===p.worth)+1}));
}
function compactScores(){const prior=state.rankShift,priorCash=state.rankCash;state.rankShift=state.homeShift;state.rankCash=1500;const rows=entries('legendary',state.homeRounds);state.rankShift=prior;state.rankCash=priorCash;return rows.length?rows.slice(0,3).map(p=>`<div class="compact-score"><span class="place">${p.rank}</span>${avatar(p.avatarIndex,esc(p.name))}<div><b>${esc(p.name)}</b><small>Final net worth</small></div><strong>${money(p.worth)}</strong></div>`).join(''):'<div class="small-copy" style="padding:23px 0">The first legend is still to be written.<br>Complete a ranked '+state.homeRounds+'-round '+(state.homeShift==='gravity'?'Gravity Pull':'Individual')+' game to set a record.</div>';}
function home(){
 const active=saves.filter(s=>s.stage!=='finished'),hosting=isOwner()?hub.hosting:null,live=hosting&&!['stopped','error'].includes(hosting.phase);
 return `${intro('Your next game starts here.','Start a fresh table, return to a saved game, or explore the worlds.','','GAME LAUNCHER')}
 <section class="launcher-deck"><div class="launcher-scene" style="background-image:url('${DATA.scenes[0]}')"><span class="eyebrow">YOUR WORLD. YOUR EMPIRE.</span><h2>One launcher.<br>Every game night.</h2><span class="launcher-location">Richmond Hill & the worlds beyond</span></div>
 <div class="launcher-controls"><span class="eyebrow">${isOwner()?'YOUR HOST PC':'YOUR GAME HOST'}</span><h2>${hosting?hosting.phase==='ready'?(mode()==='online'?'Online game ready':'Local game ready'):live?'Getting your game ready…':'Ready when you are.':'Choose your table.'}</h2>
 <p>${hosting?(live?'Hosting stays active when you minimize the Windows launcher.':'Your connection settings and match defaults are remembered.'):'Create or join a room on this host, or return to your saved seat.'}</p>
 <div class="launcher-primary">${ready()&&hub?`<button class="button" data-action="return-game">${icon('play')} Return to Game</button>`:''}<button class="button secondary" data-action="host-local">${icon('wifi')} Host Local Multiplayer</button><button class="button secondary" data-action="host-online">${icon('globe')} Host Online Players</button><button class="text-link" data-action="join">Join with a room code ${icon('arrow')}</button></div>
 ${hosting?.canExitLauncher?`<button class="button secondary" data-action="exit-game">Exit Game</button>`:''}
 ${hosting&&live?`<div class="launcher-live"><span>${pill(esc(hosting.phase==='ready'?'Hosting active':hosting.phase),'gold')}</span><button class="text-link" data-action="copy-player-link">Copy player link</button><button class="text-link" data-action="stop-hosting">Stop hosting</button></div>`:''}
 </div></section>
 <div class="launcher-shortcuts">${[['saves','save','Saved games','Pick up where you left off'],['learn','book','Learn the game','Rules, properties & all three boards'],['ranks','trophy','Rankings & records','Every mode, every round limit']].map(([page,im,title,copy])=>`<a href="#${page}" class="panel launcher-shortcut">${icon(im)}<span><b>${title}</b><small>${copy}</small></span>${icon('arrow')}</a>`).join('')}</div>
 <section><div class="section-head"><div><h2>Continue a game</h2><p>${isOwner()?'Unfinished rooms saved on this PC.':'Your saved seats at this address.'}</p></div><a href="#saves" class="text-link">All saved games ${icon('arrow')}</a></div><div class="save-grid">${active.length?active.slice(0,2).map(saveCard).join(''):`<div class="empty">${hub?'No unfinished games yet. Start a new game above.':'Loading your saved games…'}</div>`}</div></section>
 <p class="launcher-desktop-note">${icon('info')} On Windows, open <b>Start-Miniopoly.bat</b> for the movable launcher with Always on top, compact view and minimize to tray. The browser game stays separate.</p>`;
}
function filteredSaves(){const list=saves.filter(s=>state.saveStatus==='all'||s.stage===state.saveStatus);return list.length?list.map(saveCard).join(''):'<div class="empty">No saved rooms match this view.<br>Use the same browser and game address as before, or restore your player seat.</div>';}
function savedGames(){return `${intro('Your saved games.','Return to the same table with its players, properties and rules intact.',`<button class="button secondary" data-action="import">${icon('upload')} Restore player seat</button>`,'PICK UP & PLAY')}<div class="toolbar"><label>Status<select id="saveStatus"><option value="all">All saved rooms</option>${[['playing','In progress'],['lobby','Waiting rooms'],['finished','Completed']].map(([v,label])=>`<option value="${v}" ${state.saveStatus===v?'selected':''}>${label}</option>`).join('')}</select></label><span class="small-copy">${isOwner()?'Saved on this host PC':'Your saved seats in this browser'} · Most recent first</span><button class="text-link" data-action="refresh">Refresh ${icon('clock')}</button></div><div class="saved-list" id="savedList">${filteredSaves()}</div><div class="info-note">${icon('shield')}<span>A saved match remains on the host PC. Your browser or private seat backup identifies your player when you resume. Game Launcher never assigns you another player's seat.</span></div>`;}
function hostView(){return `${intro('Make room for a game night.','Choose how friends will connect, then set your match rules.','','HOST & JOIN')}${isOwner()?`<div class="host-current">Hosting ${esc(hub.hosting?.phase||'stopped')} · ${mode()==='local'?'Local Multiplayer':'Online Players'}${hub.hosting?.phase==='ready'?` <button class="text-link" data-action="open-game">Open game ${icon('arrow')}</button>`:''} <button class="text-link" data-action="setup">Host Game Setup ${icon('arrow')}</button></div>`:''}<div class="host-grid">${[['local','wifi','Around the same table','Host a local game','Everyone connects through the same home Wi-Fi. Friends join from their own browser.',['Same home network','Your PC hosts the game','Room code and invitation for friends'],0],['online','globe','Different places. One game.','Host an online game','Your PC hosts a private game while friends join from their own locations.',['Your existing private HTTPS link','Password-protected access','Keep the host PC awake during play'],2]].map(([type,im,caption,title,copy,features,world])=>`<section class="panel host-mode"><div class="host-banner" style="background-image:url('${DATA.scenes[world]}')"><span>${icon(im)} ${caption}</span></div><div class="host-mode-body"><h2>${title}</h2><p>${copy}</p><ul class="feature-list">${features.map(f=>`<li>${icon('check')} ${f}</li>`).join('')}</ul><button class="button" data-action="host-${type}">Set up ${type} play ${icon('arrow')}</button></div></section>`).join('')}</div><section class="join-band"><div><h2>Already have a place at the table?</h2><p>Join with the room code or invitation your host shared.</p></div><button class="button secondary" data-action="join">Join a friend’s game ${icon('arrow')}</button></section>`;}
function rankingView(){const express=['express','countdown'].includes(state.rankGameMode);if(express)state.rankType='standings';const rows=entries(),unlimited=state.rankRounds===0||express,eligible=[10,15,20].includes(state.rankRounds)&&state.rankCash===1500;return `${intro('Good games become great stories.','Real records and finished matches from this game host.','','HALL OF FAME')}<section class="ranking-head"><div><span class="eyebrow">A PLACE AMONG THE LEGENDS</span><h2>Every mode gets its moment.</h2><p>Individual and Gravity Pull have separate Legendary records.<br>Explore completed-match standings for every mode.</p></div><span class="rank-trophy">${icon('trophy')}</span></section><div class="rank-controls"><label>Game mode<select id="rankGameMode"><option value="classic" ${!express?'selected':''}>Classic</option><option value="express" ${state.rankGameMode==='express'?'selected':''}>Express · World Collapse</option><option value="countdown" ${state.rankGameMode==='countdown'?'selected':''}>Express · Tsunami</option></select></label>${state.rankGameMode==='express'?`<label>Final Showdown<select id="rankRentBoost"><option value="normal">Normal rent</option><option value="boost" ${state.rankRentBoost?'selected':''}>50% more rent during collapse</option></select></label>`:''}<div class="rank-rounds" aria-label="Round limit">${(express?[10,15,20]:[10,12,15,20,30,50,0]).map(n=>`<button class="mode-chip ${state.rankRounds===n?'active':''}" aria-pressed="${state.rankRounds===n}" data-rank-round="${n}">${n?n+' rounds':'Unlimited'}</button>`).join('')}</div><label>World shift<select id="rankShift"><option value="individual" ${state.rankShift==='individual'?'selected':''}>Individual</option><option value="gravity" ${state.rankShift==='gravity'?'selected':''}>Gravity Pull</option></select></label><label>Starting cash<select id="rankCash">${[1000,1500,2000].map(n=>`<option value="${n}" ${state.rankCash===n?'selected':''}>${money(n)}</option>`).join('')}</select></label></div><div class="tabs rank-tabs" role="tablist" aria-label="Ranking view"><button role="tab" class="tab" ${express?'disabled':''} aria-selected="${state.rankType==='legendary'}" tabindex="${state.rankType==='legendary'?'0':'-1'}" data-rank-type="legendary">${icon('trophy')} Legendary records</button><button role="tab" class="tab" aria-selected="${state.rankType==='standings'}" tabindex="${state.rankType==='standings'?'0':'-1'}" data-rank-type="standings">${icon('people')} Mode standings</button></div><div class="section-head"><div><h2>${express?'Express · '+state.rankRounds+' building rounds':unlimited?'Unlimited':state.rankRounds+'-round'} ${state.rankType==='legendary'?'legends':'results'}</h2><p>${state.rankShift==='gravity'?'Gravity Pull':'Individual shifts'} · ${money(state.rankCash)} start · ${express?'Survival places within each completed game':unlimited?'Completed games and their final places':'Final net worth'} · ${rows.length} recorded finishes</p></div><button class="text-link" data-action="scoring">How rankings work ${icon('info')}</button></div>${!rows.length?`<div class="empty">${state.rankType==='legendary'&&!eligible?'Legendary records require 10, 15 or 20 rounds and $1,500 starting cash. Each world-shift mode has its own records. Choose Mode standings for this mode.':'No completed results for this view yet. Finish a game to start the record book.'}</div>`:`${state.rankType==='legendary'?`<div class="podium">${rows.slice(0,3).map((p,i)=>`<article class="podium-card ${i===0?'first':''}">${i===0?`<span class="crown">${icon('crown')}</span>`:''}<span class="place-medal">#${p.rank}</span>${avatar(p.avatarIndex,p.name)}<h3>${esc(p.name)}</h3><strong>${money(p.worth)}</strong><small>FINAL NET WORTH</small></article>`).join('')}</div>`:''}<div class="rank-table-wrap"><table class="rank-table"><caption>${state.rankType==='legendary'?'The record book':unlimited?'Unlimited match results':'Completed match standings'}</caption><thead><tr><th scope="col">${unlimited?'PLACE IN GAME':'RANK'}</th><th scope="col">PLAYER</th><th scope="col">FINAL NET WORTH</th><th scope="col">GAME</th><th scope="col">FINISHED</th></tr></thead><tbody>${rows.map(p=>`<tr><td class="table-rank">${express?p.place:p.bankrupt?'OUT':unlimited?gamePlace(p):p.rank}</td><td><span class="table-player">${avatar(p.avatarIndex,p.name)}${esc(p.name)}</span></td><td class="net">${money(p.worth)}</td><td>${esc(p.roomName)}${state.rankType==='standings'?`<span class="record-label">${express?'Express':p.ranked?'Ranked':'Practice'} game</span>`:''}${unlimited?`<span class="record-label">${p.roundsPlayed} rounds played</span>`:''}</td><td>${p.at?when(Date.parse(p.at)):'Recorded previously'}</td></tr>`).join('')}</tbody></table></div>`}<div class="info-note">${icon('info')}<span>${state.rankType==='legendary'?'Individual and Gravity Pull ranked games enter separate Legendary tables. Play 10, 15 or 20 rounds with $1,500 starting cash and unchanged rules. Existing records are retained.':express?'Express results show survival places per game. Classic records and the two Final Showdown settings stay separate.':unlimited?'Unlimited shows each game’s final places, rather than comparing uncapped wealth between games.':'Each finish comes from a completed saved match, with different round limits, starting cash and shift modes kept separate.'} No example scores are shown.</span></div>`;}
function gamePlace(entry){const record=hub?.records.find(r=>r.matchId===entry.matchId);if(['express','countdown'].includes(record?.gameMode))return entry.place||record.standings.findIndex(p=>p.seat===entry.seat)+1;return record?record.standings.findIndex(p=>!p.bankrupt&&p.worth===entry.worth)+1:'—';}
function scoringDialog(){modal('A fair place for every mode.','HOW RANKINGS WORK',`<p class="dialog-description">Individual and Gravity Pull have separate Legendary records for 10, 15 and 20 rounds. Both require $1,500 starting cash and unchanged rules. Mode standings show real completed matches for each round limit and world-shift mode.</p><div class="dialog-summary"><div class="summary-row"><span>Net worth</span><b>Cash + unmortgaged deed value<br>+ half the upgrade costs</b></div><div class="summary-row"><span>Equal net worth</span><b>Players share a rank</b></div><div class="summary-row"><span>Unlimited</span><b>Final places within each game</b></div></div><p class="small-copy">Results are retained when a room starts another match. Imported older completed rooms appear in mode standings without being promoted into Legendary records. This does not change gameplay scoring.</p><div class="dialog-actions"><button class="button" data-action="close">Got it</button></div>`);}
function render(){const item=navItems.find(n=>n[0]===state.page)||navItems[0];document.getElementById('breadcrumb').innerHTML='YOUR TABLE / <b>'+item[2].toUpperCase()+'</b>';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===state.page);if(a.dataset.nav===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('main').innerHTML=(centralError?`<div class="app-error" role="alert">${esc(centralError)} <button class="text-link" data-action="refresh">Try again</button></div>`:'')+(state.page==='home'?home():state.page==='saves'?savedGames():state.page==='host'?hostView():state.page==='learn'?learnView():rankingView());if(state.page==='learn'&&state.learnTab==='properties')updateProperties();}
function go(page){closeDialog();if(!navItems.some(n=>n[0]===page))page='home';if(location.hash==='#'+page){state.page=page;render();}else location.hash=page;window.scrollTo({top:0,behavior:'auto'});}
async function refreshCentral(){if(refreshing)return;refreshing=true;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const response=await fetch('/api/central',{method:'POST',headers:{'Content-Type':'application/json',...(ownerToken?{Authorization:'Bearer '+ownerToken}:{})},body:JSON.stringify({seats:window.MiniopolySeats.list(localStorage)}),signal:controller.signal});const data=await response.json();if(!response.ok){if(response.status===401&&!ownerToken){location.reload();return;}throw Error(data.error||'Could not load your saved games.');}hub=data;saves=data.rooms||[];if(isOwner())Object.assign(defaults,data.hosting?.gameSettings||{});centralError='';document.getElementById('profileAvatar').src=DATA.avatars[avatarIndex(saves.find(s=>s.viewerName)?.players.find(p=>p.name===saves.find(s=>s.viewerName)?.viewerName)?.avatar)];document.getElementById('profileAvatar').alt=profileName()+' avatar';document.querySelector('.profile>span').innerHTML=esc(profileName())+'<small>Your game space</small>';document.getElementById('connectionStatus').textContent=isOwner()?'Host PC · '+(hub.hosting?.phase||'stopped'):mode()==='online'?'Online Players':'Local Multiplayer';if(!document.getElementById('dialog').open&&!document.activeElement?.matches('input,select'))render();}catch(error){centralError=error.name==='AbortError'?'The host did not answer in time. Your saved games have not changed.':error.message;render();}finally{clearTimeout(timer);refreshing=false;}}
function setup(modeWanted=mode(),resume='',create=false){if(isOwner()){const target=new URL('/setup',location.origin);target.searchParams.set('mode',modeWanted);if(create)target.searchParams.set('create','1');if(resume)target.searchParams.set('resume',resume);target.hash=ownerToken;if(window.MiniopolyDesktopLauncher){location.assign(target.href);return;}const opened=window.open(target.href,'miniopoly-owner-setup');if(!opened)toast('Allow the Host Game Setup window to open.');return;}let base='';try{base=localStorage.getItem('miniopoly_setup_console_v1')||'';}catch{}if(base){const target=new URL('/setup',base);target.searchParams.set('mode',modeWanted);if(create)target.searchParams.set('create','1');const opened=window.open(target.href,'miniopoly-owner-setup');if(opened)return;}modal('Open Host Game Setup on the host PC.','LOCAL / ONLINE HOSTING',`<p class="dialog-description">Use <b>Start-Miniopoly.bat</b> on the Windows host to open Game Launcher and its Local / Online setup. The game server must be stopped before changing connection modes.</p><p class="small-copy">Existing passwords, certificates and saved rooms stay in the host’s Windows user folder. A browser on another computer cannot start or reconfigure that PC.</p><div class="dialog-actions"><button class="button" data-action="close">Got it</button></div>`);}
function gameURL(parameters={}){const origin=isOwner()?hub.hosting?.url:location.origin;if(!origin)throw Error('Start hosting before opening this game.');const target=new URL('/',origin);for(const [key,value]of Object.entries(parameters))target.searchParams.set(key,value);if(isOwner()){target.searchParams.set('setupConsole',location.origin);if(hub.hosting?.avatarProfileKey)target.hash='avatarProfile='+hub.hosting.avatarProfileKey;}return target.href;}
async function openGame(parameters={}){if(isOwner()&&!ready()){setup(mode(),parameters.room||'');return;}try{const url=gameURL(parameters);if(isOwner()&&hub.hosting?.canExitLauncher){const response=await fetch('/api/launcher/open',{method:'POST',headers:{Authorization:'Bearer '+ownerToken,'Content-Type':'application/json'},body:JSON.stringify({url})});const result=await response.json();if(!response.ok)throw Error(result.error||'Could not open the game.');}else if(isOwner()){if(!window.open(url,'miniopoly-game'))toast('Allow the game window to open.');}else location.assign(url);}catch(error){toast(error.message);}}
function hostDialog(type){if(!hub)return toast('Wait for Game Launcher to connect.');if((isOwner()&&!ready())||type!==mode())return setup(type,'',true);state.hostMode=type;modal('Your next game starts here.','HOST A NEW GAME',`<p class="dialog-description">Your ${type==='online'?'online':'local'} host is ready. Choose the room rules, then choose and confirm your avatar and game piece on the next screen.</p><form id="hostForm"><label class="form-label">Game mode<select name="gameMode"><option value="classic">Classic</option><option value="express">Express · World Collapse</option><option value="countdown">Express · Tsunami</option></select></label><p class="small-copy">Express: two starting homes and a permit, GO property rewards, then collapse after 10, 15 or 20 building rounds. Last player standing wins.</p><label class="form-label">Your name<input name="hostName" maxlength="18" required value="${esc(profileName())}"></label><label class="form-label">Game name<input name="gameName" maxlength="40" value="Game night" required></label><div class="form-grid"><label class="form-label">Players<select name="count">${[2,3,4].map(n=>`<option value="${n}" ${Number(defaults.capacity)===n?'selected':''}>${n} players</option>`).join('')}</select></label><label class="form-label">Match length<select name="rounds">${[10,12,15,20,30,50,0].map(n=>`<option value="${n}" ${Number(defaults.rounds)===n?'selected':''}>${n?n+' rounds':'Unlimited'}</option>`).join('')}</select></label></div><div class="form-grid"><label class="form-label">World shift<select name="shift"><option value="individual">Individual</option><option value="gravity" ${defaults.worldShift==='gravity'?'selected':''}>Gravity Pull</option></select></label><label class="form-label">Starting cash<select name="cash">${[1000,1500,2000].map(n=>`<option value="${n}" ${Number(defaults.startingCash)===n?'selected':''}>${money(n)}</option>`).join('')}</select></label></div><label class="form-label" data-host-collapse-rent hidden><input style="width:18px;min-height:18px" type="checkbox" name="collapseRentBoost"> Final Showdown · 50% more rent during collapse</label><label class="form-label" style="display:flex;align-items:center"><input style="width:18px;min-height:18px" type="checkbox" name="ranked" ${defaults.ranked?'checked':''}> Ranked game</label><p class="small-copy">Ranked matches require 10, 15 or 20 rounds and $1,500 starting cash. Individual and Gravity Pull have separate Legendary records. Changing match rules makes the game practice.</p><div class="dialog-actions"><button type="button" class="button secondary" data-action="close">Back</button><button class="button" type="submit">Choose avatar &amp; piece ${icon('arrow')}</button></div></form>`);checkRanked();}
function checkRanked(){const form=document.getElementById('hostForm');if(!form)return;const express=['express','countdown'].includes(form.elements.gameMode.value);form.querySelector('[data-host-collapse-rent]').hidden=form.elements.gameMode.value!=='express';for(const option of form.elements.rounds.options)option.disabled=express&&![10,15,20].includes(Number(option.value));if(express&&![10,15,20].includes(Number(form.elements.rounds.value)))form.elements.rounds.value='10';const allowed=!express&&[10,15,20].includes(Number(form.elements.rounds.value))&&Number(form.elements.cash.value)===1500;form.elements.ranked.disabled=!allowed;if(!allowed)form.elements.ranked.checked=false;}
function resumeDialog(code){const save=saves.find(s=>s.code===code);if(!save)return;if(save.stage==='finished')return resultsDialog(code);modal(esc(save.name),'RESUME YOUR SAVED GAME',`<p class="dialog-description">The saved board, current turn, ownership and rules will be restored.</p><div class="dialog-summary"><div class="summary-row"><span>Progress</span><b>${save.stage==='lobby'?'Waiting room':save.rounds?'Round '+save.round+' of '+save.rounds:'Round '+save.round+' · Unlimited'}</b></div><div class="summary-row"><span>World shift</span><b>${save.worldShift==='gravity'?'Gravity Pull':'Individual'}</b></div><div class="summary-row"><span>Next turn</span><b>${esc(save.turnName||'Host starts the game')}</b></div>${save.viewerName?`<div class="summary-row"><span>Your seat</span><b>${esc(save.viewerName)}</b></div>`:''}</div><div class="resume-players">${save.players.map(p=>`<div class="resume-player">${avatar(avatarIndex(p.avatar),p.name)}<span class="player-resume-text"><b>${esc(p.name)}</b><small>${DATA.worlds[p.board].name}</small></span><strong>${money(p.cash)}<small>Cash</small></strong></div>`).join('')}</div><p class="privacy-copy">Use the same game address and browser as before. If its saved seat is unavailable, restore your private player seat file on the game screen.</p><div class="dialog-actions"><button class="button secondary" data-action="close">Back</button><button class="button" data-action="resume-confirm" data-id="${save.code}">${isOwner()&&!ready()?'Start hosting to resume':'Resume game'} ${icon('arrow')}</button></div>`);}
function resultsDialog(code){const record=(hub?.records||[]).find(r=>r.roomCode===code);if(!record)return toast('No final standings are available for this room yet.');modal(esc(record.name),'FINAL RESULTS',`<p class="dialog-description">${record.roundLimit?record.roundLimit+' rounds':'Unlimited'} · ${record.worldShift==='gravity'?'Gravity Pull':'Individual shifts'} · ${when(Date.parse(record.at))}</p><div class="resume-players">${record.standings.map((p,i)=>`<div class="resume-player">${avatar(avatarIndex(p.avatar),p.name)}<span class="player-resume-text"><b>${record.gameMode==='express'?p.place:p.bankrupt?'OUT':gamePlace({...p,matchId:record.matchId})}. ${esc(p.name)}</b><small>${p.outReason==='countdown'?'Portfolio submerged':p.outReason==='collapse'?'Lost to World Collapse':p.bankrupt?'Bankrupt':'Final net worth'}</small></span><strong>${money(p.worth)}</strong></div>`).join('')}</div><div class="dialog-actions"><button class="button" data-action="close">Back</button></div>`);}
function importSeat(){if(isOwner()){if(!ready())return setup(mode());return openGame({restore:'1'});}document.getElementById('restoreSeatFile').click();}
async function readSeat(file){try{if(file.size>2048)throw Error('Choose a Miniopoly player seat file, not a full game save.');const seat=JSON.parse(await file.text());if(seat.format!=='miniopoly-seat-v1'||!window.MiniopolySeats.valid(seat))throw Error('That is not a valid Miniopoly player seat file.');const response=await fetch('/api/resume',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:seat.code,token:seat.token})});const value=await response.json();if(!response.ok)throw Error(value.error||'That saved seat could not be restored.');window.MiniopolySeats.remember(localStorage,seat);await refreshCentral();toast('Your '+value.state.players.find(p=>p.id===value.state.youId).name+' seat is ready. Select Continue to resume.');}catch(error){toast(error.message);}}
async function launcherAction(action){
 if(action==='return-game')return openGame({});
 if(action==='exit-game'&&isOwner()&&hub.hosting?.canExitLauncher){
  const live=!['stopped','error'].includes(hub.hosting.phase);
  if(live&&!confirm('Exit Game and stop hosting? Miniopoly windows will close and connected players will disconnect. Your saved matches stay saved.'))return;
  try{const response=await fetch('/api/launcher/exit',{method:'POST',headers:{Authorization:'Bearer '+ownerToken,'Content-Type':'application/json'},body:'{}'}),value=await response.json();if(!response.ok)throw Error(value.error);toast('Closing Miniopoly…');}catch(error){toast(error.message);}return;
 }
 if(action==='copy-player-link'){try{await navigator.clipboard.writeText(hub.hosting.inviteUrl||hub.hosting.url);toast('Player link copied. Share the online password separately.');}catch{toast('Player link: '+(hub.hosting.inviteUrl||hub.hosting.url));}return;}
 if(action==='stop-hosting'&&isOwner()&&confirm('Stop hosting? Connected players will disconnect. Saved matches stay on this PC.')){
  try{const response=await fetch('/api/stop',{method:'POST',headers:{Authorization:'Bearer '+ownerToken,'Content-Type':'application/json'},body:'{}'}),value=await response.json();if(!response.ok)throw Error(value.error);await refreshCentral();toast('Hosting stopped. Your saved games are safe.');}catch(error){toast(error.message);}
 }
}
function runAction(action,button){if(['return-game','copy-player-link','stop-hosting','exit-game'].includes(action))return launcherAction(action);if(action==='close')return closeDialog();if(action==='host-local')return hostDialog('local');if(action==='host-online')return hostDialog('online');if(action==='setup')return setup();if(action==='open-game')return openGame({central:'1'});if(action==='resume'||action==='save-info')return resumeDialog(button.dataset.id);if(action==='resume-confirm')return openGame({room:button.dataset.id,resume:button.dataset.id});if(action==='refresh')return refreshCentral();if(action==='import')return importSeat();if(action==='world'||action==='worlds'){state.learnTab='boards';state.world=Number(button.dataset.world)||0;return go('learn');}if(action==='rules'||action==='first-game'||action==='properties'){state.learnTab=action==='first-game'?'overview':action==='rules'?'rules':'properties';return go('learn');}if(action==='property')return propertyDialog(button.dataset.id);if(action==='space')return spaceDialog(Number(button.dataset.world),Number(button.dataset.position));if(action==='scoring')return scoringDialog();if(action==='profile')return modal(esc(profileName()),'YOUR GAME SPACE',`<p class="dialog-description">${isOwner()?'You are using the private host-PC console. Its control link stays on this PC.':'Your saved player seats belong to this browser and game address.'}</p><p class="small-copy">Use Save my seat from the live game to keep a private backup before changing browsers or game addresses.</p><div class="dialog-actions"><button class="button" data-action="close">Back</button></div>`);if(action==='feedback')return modal('Welcome to Game Launcher.','HELP & HOSTING',`<p class="dialog-description">Saved games use this host’s saved match and your existing player seat. Learn the Game is available before joining a room. Hall of Fame shows actual completed results.</p><div class="help-links"><button data-action="import">Restore a player seat ${icon('arrow')}</button><button data-action="setup">Host Game Setup ${icon('arrow')}</button><button data-action="worlds">Explore the worlds ${icon('arrow')}</button></div>`);if(action==='join')return modal('There’s a seat waiting for you.','JOIN A GAME',`<p class="dialog-description">Enter the six-character room code. For a game hosted elsewhere, use the private invitation link shared by that host.</p><form id="joinGameForm"><label class="form-label">Room code<input name="code" maxlength="6" minlength="6" pattern="[A-Za-z2-9]{6}" required placeholder="ABC234" autocomplete="off"></label><p class="small-copy">Choose and confirm your avatar and game piece on the game screen. Existing players resume their saved seat when available.</p><div class="dialog-actions"><button class="button secondary" type="button" data-action="close">Back</button><button class="button" type="submit">Continue to game ${icon('arrow')}</button></div></form>`);}
document.addEventListener('click',event=>{const action=event.target.closest('[data-action]');if(action)return runAction(action.dataset.action,action);const learn=event.target.closest('[data-learn-tab]');if(learn){state.learnTab=learn.dataset.learnTab;render();document.querySelector(`[data-learn-tab="${state.learnTab}"]`)?.focus({preventScroll:true});return;}const world=event.target.closest('[data-world-select]');if(world){state.world=Number(world.dataset.worldSelect);render();document.querySelector(`[data-world-select="${state.world}"]`)?.focus({preventScroll:true});return;}const round=event.target.closest('[data-rank-round]');if(round){state.rankRounds=Number(round.dataset.rankRound);if(![10,15,20].includes(state.rankRounds))state.rankType='standings';render();document.querySelector(`[data-rank-round="${state.rankRounds}"]`)?.focus({preventScroll:true});return;}const type=event.target.closest('[data-rank-type]');if(type){state.rankType=type.dataset.rankType;render();document.querySelector(`[data-rank-type="${state.rankType}"]`)?.focus({preventScroll:true});}});
document.addEventListener('change',event=>{const e=event.target;if(e.id==='homeShift'){state.homeShift=e.value;document.getElementById('compactScores').innerHTML=compactScores();}if(e.id==='homeRounds'){state.homeRounds=Number(e.value);document.getElementById('compactScores').innerHTML=compactScores();}if(e.id==='saveStatus'){state.saveStatus=e.value;document.getElementById('savedList').innerHTML=filteredSaves();}if(e.id==='propertyWorld'||e.id==='propertyType'){state[e.id]=e.value;updateProperties();}if(e.id==='rankCash'){state.rankCash=Number(e.value);if(state.rankCash!==1500)state.rankType='standings';render();document.getElementById('rankCash')?.focus({preventScroll:true});}if(e.id==='rankGameMode'){state.rankGameMode=e.value;if(['express','countdown'].includes(e.value)){state.rankType='standings';if(![10,15,20].includes(state.rankRounds))state.rankRounds=10;}render();}if(e.id==='rankRentBoost'){state.rankRentBoost=e.value==='boost';render();}if(e.id==='rankShift'){state.rankShift=e.value;render();document.getElementById('rankShift')?.focus({preventScroll:true});}if(e.closest('#hostForm'))checkRanked();});
document.addEventListener('input',event=>{if(event.target.id==='propertySearch'){state.propertySearch=event.target.value;updateProperties();}});
document.addEventListener('submit',event=>{if(event.target.id==='hostForm'){event.preventDefault();const form=new FormData(event.target),settings={gameMode:form.get('gameMode'),collapseRentBoost:form.get('collapseRentBoost')==='on',hostName:form.get('hostName'),capacity:Number(form.get('count')),rounds:Number(form.get('rounds')),startingCash:Number(form.get('cash')),worldShift:form.get('shift'),ranked:form.get('ranked')==='on'};openGame({new:'1',hostSetup:JSON.stringify(settings),roomName:form.get('gameName')});}if(event.target.id==='joinGameForm'){event.preventDefault();const form=new FormData(event.target);openGame({room:String(form.get('code')).toUpperCase()});}});
document.getElementById('restoreSeatFile').addEventListener('change',event=>{const file=event.target.files?.[0];event.target.value='';if(file)void readSeat(file);});
document.getElementById('dialog').addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});});
document.getElementById('dialog').addEventListener('click',event=>{if(event.target===event.currentTarget){const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
document.addEventListener('keydown',event=>{const tab=event.target.closest('[role=tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...tab.closest('[role=tablist]').querySelectorAll('[role=tab]')],index=tabs.indexOf(tab),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();});
function route(){const page=location.hash.slice(1);state.page=navItems.some(n=>n[0]===page)?page:'home';render();}
window.addEventListener('hashchange',()=>{route();document.getElementById('main').focus({preventScroll:true});});
window.addEventListener('pageshow',()=>void refreshCentral());document.addEventListener('visibilitychange',()=>{if(!document.hidden)void refreshCentral();});setInterval(()=>{if(!document.hidden)void refreshCentral();},15000);route();void refreshCentral();
